function dateKey(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),day=String(d.getDate()).padStart(2,"0");return `${y}-${m}-${day}`}
function parseDateKey(k){const [y,m,d]=k.split("-").map(Number);return new Date(y,m-1,d)}
function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function dayNumber(d=new Date()){return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/86400000)}
function challengeNumber(d=new Date()){return dayNumber(d)-Math.floor(Date.UTC(2026,0,1)/86400000)+1}
function hashString(str){let h=2166136261;for(let i=0;i<str.length;i++){h^=str.charCodeAt(i);h=Math.imul(h,16777619)}return h>>>0}
function mulberry32(a){return function(){let t=a+=0x6D2B79F5;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
function shuffled(arr,seed){const r=mulberry32(seed),copy=[...arr];for(let i=copy.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[copy[i],copy[j]]=[copy[j],copy[i]]}return copy}

/* ===== DAILY SCHEDULER ===== */
const SPECIAL_THEMES=["Años 90","Chile","Internet","Música latinoamericana"];
function proposedSpecialTheme(d){return d.getDay()===3?SPECIAL_THEMES[Math.abs(Math.floor(dayNumber(d)/7))%SPECIAL_THEMES.length]:""}
function sustainableCooldown(diff){const count=SCHEDULE_BANK.filter(q=>q.difficulty===diff).length,quota=DIFFICULTY_QUOTA[diff];return Math.min(TARGET_COOLDOWN_DAYS,Math.max(30,Math.floor(count/quota)-1))}
function recentQuestionsForScore(history,n,days=14){return history.filter(x=>n-x.day<=days).map(x=>x.q)}
function diversityScore(q,key,slot,chosen,recent,weekCategories){
  let score=(hashString(`${CONTENT_VERSION}|${SCHEDULE_VERSION}|${key}|${slot}|${q.id}`)/4294967296)*0.2;
  const dimensions=["category","entity","region","subcategory"];
  dimensions.forEach((dim,i)=>{if(chosen.some(x=>x[dim]===q[dim]))score-=[5,8,3,4][i];if(recent.slice(-25).some(x=>x[dim]===q[dim]))score-=[1.3,3.2,.8,1.5][i]});
  if(chosen.some(x=>decadeOf(x.year)===decadeOf(q.year)))score-=2.5;
  if(recent.slice(-25).filter(x=>decadeOf(x.year)===decadeOf(q.year)).length>=3)score-=1.1;
  if(!weekCategories.has(q.category))score+=4.5;
  if(q.region!=="Estados Unidos")score+=.35;
  return score;
}
function chooseForSlots({key,n,history,lastDay,theme="",themeSlots=[]}){
  const desired=shuffled(["facil","facil","media","media","dificil"],hashString(`${key}|difficulty-order|${CONTENT_VERSION}|${SCHEDULE_VERSION}`));
  const chosen=[],recent=recentQuestionsForScore(history,n),weekCategories=new Set(recentQuestionsForScore(history,n,7).map(q=>q.category));
  for(let slot=0;slot<desired.length;slot++){
    const diff=desired[slot],cool=sustainableCooldown(diff),mustTheme=theme&&themeSlots.includes(slot);
    let pool=SCHEDULE_BANK.filter(q=>q.difficulty===diff&&!chosen.some(c=>c.id===q.id)&&(lastDay.get(q.id)===undefined||n-lastDay.get(q.id)>cool)&&(!mustTheme||q.themes.includes(theme)));
    if(!pool.length)return null;
    pool.sort((a,b)=>diversityScore(b,key,slot,chosen,recent,weekCategories)-diversityScore(a,key,slot,chosen,recent,weekCategories));
    chosen.push(pool[0]);
  }
  return chosen;
}
function makeDaySchedule(key,n,history,lastDay){
  const d=parseDateKey(key),theme=proposedSpecialTheme(d);
  if(theme){
    const masks=[[0,1,2,3],[0,1,2,4],[0,1,3,4],[0,2,3,4],[1,2,3,4]];
    for(const mask of shuffled(masks,hashString(`${key}|special-mask`))){const questions=chooseForSlots({key,n,history,lastDay,theme,themeSlots:mask});if(questions&&questions.filter(q=>q.themes.includes(theme)).length>=4)return {questions,specialTheme:theme}}
  }
  return {questions:chooseForSlots({key,n,history,lastDay})||[],specialTheme:""};
}
function generateDailyScheduleThrough(targetN){
  if(targetN<=SCHEDULE_MAX_DAY)return;const epoch=new Date(2026,0,1);
  for(let n=SCHEDULE_MAX_DAY+1;n<=targetN;n++){
    const key=dateKey(addDays(epoch,n)),entry=makeDaySchedule(key,n,SCHEDULE_HISTORY,SCHEDULE_LAST_DAY);
    if(entry.questions.length!==5)throw new Error(`No fue posible construir el desafío ${key}`);
    DAILY_SCHEDULE_CACHE.set(n,entry);entry.questions.forEach(q=>{SCHEDULE_HISTORY.push({day:n,q});SCHEDULE_LAST_DAY.set(q.id,n)});
    while(SCHEDULE_HISTORY.length&&n-SCHEDULE_HISTORY[0].day>90)SCHEDULE_HISTORY.shift();SCHEDULE_MAX_DAY=n;
  }
}
function resetScheduleCache(){DAILY_SCHEDULE_CACHE.clear();SCHEDULE_HISTORY.length=0;SCHEDULE_LAST_DAY.clear();SCHEDULE_MAX_DAY=-1}
function dailyEntry(key=dateKey()){
  if(typeof HUMAN_TESTER_ACTIVE!=='undefined'&&HUMAN_TESTER_ACTIVE){
    const day=Math.floor(Date.UTC(...key.split('-').map((n,i)=>Number(n)-(i===1?1:0)))/86400000),offset=((day*5)%QUESTIONS.length+QUESTIONS.length)%QUESTIONS.length;
    return {questions:Array.from({length:5},(_,i)=>QUESTIONS[(offset+i)%QUESTIONS.length]),specialTheme:null};
  }
  if(typeof PUBLISHED_CALENDAR!=='undefined'&&PUBLISHED_CALENDAR.has(key)){const row=PUBLISHED_CALENDAR.get(key);return {questions:row.ids.map(id=>SCHEDULE_BANK.find(q=>q.id===id)),specialTheme:row.specialTheme}}
  const epoch=new Date(2026,0,1),d=parseDateKey(key),n=challengeNumber(d)-1;
  if(n<0){const last=new Map(),history=[];return makeDaySchedule(key,Math.abs(n),history,last)}
  generateDailyScheduleThrough(n);return DAILY_SCHEDULE_CACHE.get(n);
}
function dailyQuestions(key=dateKey()){return dailyEntry(key).questions.map(q=>QUESTION_BY_ID.get(q.id))}
function reservedUpcomingIds(days=7){if(typeof HUMAN_TESTER_ACTIVE!=='undefined'&&HUMAN_TESTER_ACTIVE)days=0;const ids=new Set();for(let i=0;i<=days;i++)dailyQuestions(dateKey(addDays(new Date(),i))).forEach(q=>ids.add(q.id));return ids}

